fn put_f64(out:*mut u8,offset:usize,x:f64){let b=x.to_le_bytes();unsafe{for k in 0..8{*out.add(offset+k)=b[k];}}}
#[no_mangle]
pub unsafe extern "C" fn n_body_simulation(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{
 if v.is_null()||n<6{return -1}let (nb,steps,dtm,gm,tf,sm)=(*v,*v.add(1),*v.add(2),*v.add(3),*v.add(4),*v.add(5));if !(2..=4).contains(&nb)||!(0..=4).contains(&steps)||!(1..=1000).contains(&dtm)||!(0..=1000).contains(&gm)||!(1..=10).contains(&tf)||!(1..=3000).contains(&sm)||n!=6+5*nb as usize{return -1}let count=nb as usize;let mut x=[0.0;4];let mut y=[0.0;4];let mut vx=[0.0;4];let mut vy=[0.0;4];let mut mass=[0.0;4];for i in 0..count{let a=*v.add(6+5*i);let b=*v.add(7+5*i);let c=*v.add(8+5*i);let d=*v.add(9+5*i);let m=*v.add(10+5*i);if !(-1000..=1000).contains(&a)||!(-1000..=1000).contains(&b)||!(-100..=100).contains(&c)||!(-100..=100).contains(&d)||!(1..=1000).contains(&m){return -1}x[i]=a as f64;y[i]=b as f64;vx[i]=c as f64;vy[i]=d as f64;mass[i]=m as f64;}let dt=(dtm as f64/1000.0)*tf as f64;let g=gm as f64/1000.0;let soft=sm as f64/1000.0;for _ in 0..steps{for i in 0..count{let(mut fx,mut fy)=(0.0,0.0);for j in 0..count{if i!=j{let dx=x[j]-x[i];let dy=y[j]-y[i];let dist=(dx*dx+dy*dy+soft).sqrt();let cube=dist*dist*dist;fx+=g*mass[j]*dx/cube;fy+=g*mass[j]*dy/cube;}}vx[i]+=fx*dt;vy[i]+=fy*dt;}for i in 0..count{x[i]+=vx[i]*dt;y[i]+=vy[i]*dt;}}let bytes=count*32;if out.is_null()||cap<bytes{return -2}for i in 0..count{put_f64(out,(4*i)*8,x[i]);put_f64(out,(4*i+1)*8,y[i]);put_f64(out,(4*i+2)*8,vx[i]);put_f64(out,(4*i+3)*8,vy[i]);}bytes as i64
}
